function generate(opts){ opts=opts||{};
  var parts=['<div class="wf-header">Header</div>'];
  if(opts.sidebar) parts.push('<div class="wf-sidebar">Sidebar</div>');
  parts.push('<div class="wf-main">Main Content</div>');
  parts.push('<div class="wf-footer">Footer</div>');
  return '<div class="wireframe">'+parts.join('\n')+'</div>';
}
var EXPORTS={generate:generate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WireframeForgePure = EXPORTS; }
